-- ============================================
-- 英语单词表 - 公共英语三级核心词表
-- 共 1107 词（乱序）
-- 在 Supabase SQL Editor 中执行
-- ============================================

CREATE TABLE IF NOT EXISTS english_words (
  id bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  word text NOT NULL,
  phonetic_uk text,
  phonetic_us text,
  meaning text,
  example text,
  translation text,
  initial char(1)
);

